      vx: p.vx, vy: p.vy, vz: p.vz, yaw: p.yaw, pitch: p.pitch, faceYaw: p.faceYaw,
      bank: p.bank, tilt: p.tilt, squash: p.squash, grounded: p.grounded, airAmt: p.airAmt,
