    const out = { spot, inside, touchFrames: touch, hits,
      span: [+spanWas.toFixed(2), +spanNow.toFixed(2)],
      end: file.map(c => [+c.x.toFixed(2), +c.y.toFixed(2), +c.z.toFixed(2)]) };
