  check('the person is drawn, and the coat owns pixels', mr.humanCoat && mr.humanCoat.px > 300, mr.humanCoat);
  check('the person\'s collar owns pixels of its own', mr.humanCollar && mr.humanCollar.px > 300, mr.humanCollar);
